<?php class Favorite{public static function mine($uid){$s=db()->prepare('SELECT a.*,c.name category FROM favorites f JOIN activities a ON a.id=f.activity_id JOIN sport_categories c ON c.id=a.category_id WHERE f.user_id=? ORDER BY a.title');$s->execute([$uid]);return $s->fetchAll();}public static function toggle($uid,$aid){$s=db()->prepare('SELECT 1 FROM favorites WHERE user_id=? AND activity_id=?');$s->execute([$uid,$aid]);if($s->fetchColumn()){db()->prepare('DELETE FROM favorites WHERE user_id=? AND activity_id=?')->execute([$uid,$aid]);return false;}db()->prepare('INSERT INTO favorites(user_id,activity_id) VALUES(?,?)')->execute([$uid,$aid]);return true;}}